package main

import (
	"fmt"
	"go/format"
	"log"
	"sort"
	"strings"

	"github.com/tucats/govax/internal/lbr"
	"github.com/tucats/govax/internal/obj"
)

// libraryFile is the generated file that holds LibrarySymbols, in
// internal/vmsdef.
const libraryFile = "library_generated.go"

// readLibrary reads an object library, such as STARLET.OLB, and returns
// the absolute symbols its definition modules define, and how many such
// modules there were. A definition module is one that adds nothing to an
// image but symbols: STARLET's SYS$SSDEF, which defines every SS$_ code,
// say. It holds only header, GSD, and end-of-module records, and text
// records that only set the relocation base (see baseOnly); its psects
// are empty; every symbol it defines is absolute; and it refers to none.
// LINK adding such a module and LINK taking its symbols from a table make
// the same image.
//
// Each symbol's value is the one from the module the library's global
// symbol index names, which is the module LINK would add. Two modules can
// define a symbol differently: STARLET's SYS$P1_VECTOR puts SYS$CONNECT
// at its P1 vector address, and SYS$VECTOR at its address in the system
// vector, for linking against the executive; the index names
// SYS$P1_VECTOR. Only symbols whose names begin with prefix ("" for all)
// are returned.
func readLibrary(data []byte, prefix string) (map[string]uint32, int, error) {
	lib, err := lbr.Open(data)
	if err != nil {
		return nil, 0, err
	}

	if lib.Type != lbr.TypeObject {
		return nil, 0, fmt.Errorf("a %s library, not an object library", lib.Type)
	}

	if len(lib.Indexes) < 2 {
		return nil, 0, fmt.Errorf("the library has no global symbol index")
	}

	type module struct {
		defs map[string]uint32 // nil if not a definition module
	}

	modules := map[lbr.RFA]module{}
	out := map[string]uint32{}

	for _, k := range lib.Indexes[1].Keys {
		if !strings.HasPrefix(k.Name, prefix) {
			continue
		}

		m, ok := modules[k.RFA]
		if !ok {
			name, _ := lib.ModuleName(k.RFA)

			lm, err := lib.Module(k.RFA)
			if err != nil {
				return nil, 0, fmt.Errorf("module %s: %w", name, err)
			}

			om, err := obj.Decode(lm.Records)
			if err != nil {
				return nil, 0, fmt.Errorf("module %s: %w", name, err)
			}

			m.defs, _ = definitions(om)
			modules[k.RFA] = m
		}

		if v, ok := m.defs[k.Name]; ok {
			out[k.Name] = v
		}
	}

	n := 0

	for _, m := range modules {
		if m.defs != nil {
			n++
		}
	}

	return out, n, nil
}

// definitions returns the symbols m defines, if it's a definition module
// (see readLibrary).
func definitions(m *obj.Module) (map[string]uint32, bool) {
	for _, rec := range m.Records {
		switch r := rec.(type) {
		case *obj.MainHeader, *obj.TextHeader, *obj.GSD, *obj.EOM:
		case *obj.TIR:
			if r.Type != obj.RecTIR || !baseOnly(r) {
				return nil, false
			}
		default:
			return nil, false
		}
	}

	for _, p := range m.Psects() {
		if p.Alloc != 0 {
			return nil, false
		}
	}

	defs := map[string]uint32{}

	for _, s := range m.Symbols() {
		if !s.Defined() || s.Flags&obj.SymREL != 0 {
			return nil, false
		}

		defs[s.Name] = s.Value
	}

	return defs, len(defs) > 0
}

// baseOnly reports whether a text record only sets the relocation base: a
// psect's address pushed (STA_PB, STA_PW, or STA_PL) and popped into the
// base (CTL_SETRB), as STARLET's SYS$SSDEF does, storing nothing.
func baseOnly(r *obj.TIR) bool {
	for _, c := range r.Commands {
		switch c.Op.String() {
		case "STA_PB", "STA_PW", "STA_PL", "CTL_SETRB":
		default:
			return false
		}
	}

	return true
}

// generateLibrary returns the Go source of library_generated.go.
func generateLibrary(symbols map[string]uint32, sources []string) []byte {
	var b strings.Builder

	fmt.Fprintf(&b, "// Code generated by internal/vmsdef/gen. DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package vmsdef\n\n")

	fmt.Fprintf(&b, "// LibrarySources names the object libraries LibrarySymbols was built\n")
	fmt.Fprintf(&b, "// from, in the order they were first merged.\n")
	fmt.Fprintf(&b, "var LibrarySources = []string{\n")

	for _, s := range sources {
		fmt.Fprintf(&b, "\t%q,\n", s)
	}

	fmt.Fprintf(&b, "}\n\n")

	names := make([]string, 0, len(symbols))
	for n := range symbols {
		names = append(names, n)
	}

	sort.Strings(names)

	fmt.Fprintf(&b, "// LibrarySymbols is every absolute symbol the object libraries'\n")
	fmt.Fprintf(&b, "// definition modules define, by name (see images.go).\n")
	fmt.Fprintf(&b, "var LibrarySymbols = map[string]uint32{\n")

	for _, n := range names {
		fmt.Fprintf(&b, "\t%q: %#x,\n", n, symbols[n])
	}

	fmt.Fprintf(&b, "}\n")

	out, err := format.Source([]byte(b.String()))
	if err != nil {
		log.Fatalf("gen: generated library symbols don't compile: %v", err)
	}

	return out
}
